        row for row in sessions if row["状态"] != _STATE_OFFLINE
    ]
    if len(live_sessions) > self._total:
        raise ResourceError(
            f"total session limit {self._total} below "
            f"{len(live_sessions)} sessions"
        )
    per_user = {}

    per_user = {}
    for row in live_sessions:
        user = row["用户"]
